package de.littletrotter.e2e.receipts

/**
 * Deterministic, byte-exact PDF fixtures for the receipt size-boundary tests ([ReceiptBudgetE2EIT]
 * RB-4). These used to be vendored files generated by an external dataset generator (admin-tools)
 * that this repository does not carry; a test that skips when that generator's output is absent is
 * a test that silently stops proving anything on every checkout that does not also have it.
 * Building the exact byte count in-process removes the dependency entirely.
 *
 * The PDF is the smallest structurally valid single-page document: a Catalog, a Pages tree, one
 * Page, and one content stream — the last of which carries the padding, so the padding lives
 * inside a real PDF object rather than as trailing garbage a strict reader could reject. `%PDF-`
 * always begins the file, matching the magic-byte check every consumer here relies on
 * ([BoundaryPdfFixturesE2EIT] asserts this and the exact byte count directly).
 */
object BoundaryPdfFixtures {

    private const val MAX_SIZE_ADJUST_ITERATIONS = 8
    private val pdfHeader = "%PDF-1.4\n".toByteArray(Charsets.US_ASCII)
    private val obj1Catalog = "1 0 obj\n<< /Type /Catalog /Pages 2 0 R >>\nendobj\n".toByteArray(Charsets.US_ASCII)
    private val obj2Pages = "2 0 obj\n<< /Type /Pages /Kids [3 0 R] /Count 1 >>\nendobj\n".toByteArray(Charsets.US_ASCII)
    private val obj3Page = (
        "3 0 obj\n<< /Type /Page /Parent 2 0 R /MediaBox [0 0 612 792] /Contents 4 0 R " +
            "/Resources << >> >>\nendobj\n"
        ).toByteArray(Charsets.US_ASCII)

    /**
     * Builds a minimal valid one-page PDF whose serialized byte array is EXACTLY [totalBytes]
     * long. The padding (ASCII spaces — valid, no-op whitespace inside a PDF content stream) sits
     * inside object 4's stream; everything around it (offsets, `/Length`, `startxref`) is
     * recomputed from the padding's own size, so a handful of iterations converge even though the
     * padding's decimal digit count occasionally shifts the total by a byte or two.
     */
    fun exactSizePdf(totalBytes: Int): ByteArray {
        val skeletonSize = build(0).size
        require(totalBytes >= skeletonSize) {
            "totalBytes must be at least $skeletonSize bytes (the fixed PDF skeleton), was $totalBytes"
        }
        var padSize = totalBytes - skeletonSize
        repeat(MAX_SIZE_ADJUST_ITERATIONS) {
            val candidate = build(padSize)
            val diff = totalBytes - candidate.size
            if (diff == 0) return candidate
            padSize += diff
        }
        error("could not converge on an exact $totalBytes-byte PDF (last attempt used padSize=$padSize)")
    }

    private fun build(padSize: Int): ByteArray {
        val streamBody = ByteArray(padSize) { ' '.code.toByte() }
        val obj4Prefix = "4 0 obj\n<< /Length $padSize >>\nstream\n".toByteArray(Charsets.US_ASCII)
        val obj4Suffix = "\nendstream\nendobj\n".toByteArray(Charsets.US_ASCII)

        val offset1 = pdfHeader.size
        val offset2 = offset1 + obj1Catalog.size
        val offset3 = offset2 + obj2Pages.size
        val offset4 = offset3 + obj3Page.size
        val xrefOffset = offset4 + obj4Prefix.size + streamBody.size + obj4Suffix.size

        val xref = buildString {
            append("xref\n0 5\n")
            append("0000000000 65535 f \n")
            append(xrefEntry(offset1))
            append(xrefEntry(offset2))
            append(xrefEntry(offset3))
            append(xrefEntry(offset4))
        }.toByteArray(Charsets.US_ASCII)

        val trailer = "trailer\n<< /Size 5 /Root 1 0 R >>\nstartxref\n$xrefOffset\n%%EOF".toByteArray(Charsets.US_ASCII)

        return pdfHeader + obj1Catalog + obj2Pages + obj3Page + obj4Prefix + streamBody + obj4Suffix + xref + trailer
    }

    private fun xrefEntry(offset: Int): String = offset.toString().padStart(10, '0') + " 00000 n \n"
}
